    // n = (2^k - 1) - 2^i, where k >= 2, 0 <= i <= k-2
    // Limit k so that numbers don't exceed 1e18
    val maxVal = 1_000_000_000_000_000_000L
    for (k in 2..60) {
        val allOnes = (1L shl k) - 1L
        for (i in 0 until k - 1) {
