fun countUpTo(x: Long): Long {
    if (x <= 0L) return 0L
    var res = 0L
    var bit = 0
    while (true) {
        val high = 1L shl (bit + 1)
        if (high > x) break
        val low = 1L shl bit
        val start = high - 1
        val end = (high shl 1) - 2
        if (start > x) break
        if (end <= x) {
            res += (high - low)
        } else {
            res += (x - start + 1)
        }
        bit++
    }
    return res
}

