import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun countUpTo(x: Long): Long {
    if (x <= 0L) return 0L
    var res = 0L
    val bits = x.toString(2)
    val n = bits.length

    // Count numbers with exactly one zero and length < n
    for (len in 2 until n) {
        // For each position of zero (not first, not last)
        res += (len - 2).toLong()
    }

    // Count numbers with exactly one zero and length == n, <= x
    // We build numbers bit by bit, tracking whether we've placed the zero
    var placedZero = false
    for (i in 0 until n) {
        val remaining = n - i - 1
        val bit = bits[i]

        if (bit == '1') {
            // Option 1: place zero here (if allowed)
            if (!placedZero && i != 0 && i != n - 1) {
                // After placing zero, all remaining bits must be 1
                // That gives exactly one number
                res += 1L
            }
            // Option 2: place 1 here and continue (already done by following loop)
        } else { // bit == '0'
            // If we already placed zero earlier, we must put 1 here to keep <= x,
            // but that would exceed x since x has 0 here, so no further numbers.
            // If we haven't placed zero yet, we must place zero here to stay <= x.
            if (placedZero) {
                // Can't proceed further, as any 1 here would exceed x
                return res
            } else {
                // Must place zero here to match x
                placedZero = true
                // But if this position is first or last, it's invalid (leading or trailing zero)
                if (i == 0 || i == n - 1) {
                    // No valid numbers with this prefix, and we can't exceed x
                    return res
                }
            }
        }
    }

    // If we finished and placed exactly one zero, x itself is valid
    if (placedZero) res += 1L
    return res
}

